    "note": null,
    "explanation": "Rektal ateş ölçümü derin vücut ısısını en doğru yansıttığı için özellikle **yenidoğan ve ilk 3–6 aylık** infantlarda altın standart olarak tercih edilir; 6. aydan sonra travma riski ve huzursuzluk nedeniyle aksiller veya timpanik yöntemler öne çıkar. Termoregülasyon merkezi ön hipotalamusta yer alır ve normal diürnal ritimde sabah en düşük, akşam en yüksek ısı saptanır.",
