    "question": "Biyoterorizm hangi şıkta doğru anlatılmıştır?",
    "professor": "Şirin Küçük",
    "options": [
      {
        "letter": "A",
        "text": "Mikroorganizmalar ya da toksinlerinin, yalnızca insanların ölümlere sebebiyet vermek, panik oluşturmak, hastalık meydana getirmek gibi amaçlarla kişi veya gruplarca kullanılmasına biyoterörizm denilmektedir."
      },
      {
        "letter": "B",
        "text": "Sadece virüslerin, insanların ölümlere sebebiyet vermek, panik oluşturmak, hastalık meydana getirmek gibi amaçlarla kişi veya gruplarca kullanılmasına biyoterörizm denilmektedir."
      },
      {
        "letter": "C",
        "text": "Mikroorganizmalar ya da toksinlerinin, hayvanların ölümlere sebebiyet vermek, panik oluşturmak, hastalık meydana getirmek gibi amaçlarla kişi veya gruplarca kullanılmasına biyoterörizm denilmektedir."
      },
      {
        "letter": "D",
        "text": "Sadece tarımsal toksinlerin, insanların ölümlere sebebiyet vermek, panik oluşturmak, hastalık meydana getirmek gibi amaçlarla kişi veya gruplarca kullanılmasına biyoterörizm denilmektedir."
      },
      {
        "letter": "E",
        "text": "Mikroorganizmalar ya da toksinlerinin, tüm canlılarda ölümlere sebebiyet vermek, panik oluşturmak, hastalık meydana getirmek gibi amaçlarla kişi veya gruplarca kullanılmasına biyoterörizm denilmektedir."
      }
    ],
    "answer": "E",
    "note": null,
