    "q_num": 80,
    "question": "Yoğun bakımda takip edilmekte olan hastanın kan kültüründe üreme sinyali alınmış\nve besiyerine pasaj yapılmıştır. EMB agarda herhangi bir üreme saptanmazken kanlı agar\nbesiyerinde geniş hemoliz zonu olan koloniler görülmüştür. Kolonilerden yapılan katalaz ve\nkoagülaz testleri pozitif saptanmıştır. Antibiyotik duyarlılık testlerinde sefoksitine direnç\ngörülmüştür ve moleküler analizde bakteride mecA geni pozitif saptanmıştır. Bu hastanın\ntedavisinde aşağıdaki antibiyotiklerden hangisi kullanılabilir?",
