    "question": "Bulaşıcı hastalıklarla ilgili önermelerin hangisi yanlıştır?",
    "professor": "Ufuk Berberoğlu",
    "options": [
      {
        "letter": "A",
        "text": "İndeks olgunun görülmesinden itibaren o hastalık için en uzun kuluçka süresi içinde saptanan olgu sayısının duyarlı kişi sayısına bölünmesiyle primer atak hızı hesaplanır."
      },
      {
        "letter": "B",
        "text": "Primer atak hızı, salgının yaygınlığını gösterir."
      },
      {
        "letter": "C",
        "text": "Enfekte ya da hasta olan insan ya da hayvanın, hastalığın bulaştırma süresi boyunca sağlam kişilerle temasının tam olarak önlenmesine karantina denir."
      },
      {
        "letter": "D",
        "text": "En uzun ikinci kuluçka süresi içinde saptanan olgu sayısının duyarlı kişi sayısına bölünmesiyle sekonder atak hızı elde edilir."
      },
      {
        "letter": "E",
        "text": "Bağışıklık bırakmayan, tekrarlayabilen bulaşıcı hastalıkların boyutunu ölçmek için epizod hızı kullanılır."
      }
    ],
    "answer": "C",
    "note": null,
    "explanation": "Enfekte veya hasta olan bireyin bulaştırıcılık süresi boyunca sağlıklı bireylerden ayrılması işlemine karantina değil **izolasyon (yalıtım)** denir. Karantina ise enfeksiyon kaynağı ile temas etmiş fakat henüz hastalık belirtisi göstermeyen sağlıklı kişilerin en uzun kuluçka süresince tecrit ve gözlem altında tutulmasıdır.",
