    "question": "Hipertansiyon (HT) ve Koroner Kalp Hastalığı (KKH) konusunda verilen\nönermelerin doğruları hangi seçenekte verilmiştir?\n1. Son araştırmalara göre, sistolik kan basıncında en çok azalmayı egzersiz oluşturmaktadır.\n2. Kalsiyum alımının düşük olduğu toplumlarda, KKH’ın görülme sıklığı artabilir.\n3. Framingham çalışmasında, KKH açısından insan deneyleri yapılmaktadır.\n4. CDC ve AHA’ya göre kardiyovasküler hastalıklardan ölümlerinin yarısının nedeni,\nHT’dur.\n5. Son araştırmalara göre ülkemizde HT prevalansı % 30’u aşmıştır",
