    "question": "Üreme sağlığında erken tanı konusundaki önermelerin Doğru(D) ve Yanlış(Y)\nsıralaması hangi seçenektedir ?\n1. Tarama testinin duyarlılığı, hastaları saptama gücüdür.\n2. Tarama testinin seçiciliği, sağlamları saptama gücüdür.\n3. Fenilketonüri taraması için 2. Basamak sağlık kuruluşlarının desteği gerekmektedir.\n4. Tarama testleri, 1. Basamak sağlık kurumlarında, hekim tarafından uygulanmalıdır.\n5. Taramadan hemen önce, toplumun sağlık davranışları taramanın yararı doğrultusunda\ndeğiştirilmelidir.",
