    "question": "Üreme sağlığında erken tanı konusundaki önermelerin D/Y sıralaması hangi\nseçenektedir?Kadınlarda üreme sağlığı sorunlarının daha fazla görülmesinin nedenlerinden\nbirisi de; doğuşta beklenen yaşam süresinin artmasıdır.Erken tanıda kullanılan tarama\ntestinin (+) kestirim gücü (prediktif değeri), tarama testinin sağlam dediği kişilerin gerçekten\nsağlam olma olasılığıdır.Erken tanı 1. Basamak’ta olağan (rutin) çalışmalar sırasında\nkullanılabilir.Erken tanıda kullanılan dönemsel (periyodik) incelemelerde, sağlıkla ilgili yanlış\ntutumlar ortaya çıkarılır ve düzeltilmesi yönünde yol gösterilir.Erken tanıda kullanılan\ntoplum taramalarında; hastalık kuşkusu olanlar, sağlamlardan ayrılmaktadır.",
