    "explanation": "Sağlık hizmetlerinde belirgin bir \"bilgi asimetrisi\" vardır; hasta tıbbi bilgiye sahip olmadığı için tüketimin türünü ve miktarını belirleyemez, yani **hizmetin boyutunu kullanıcı değil hekim (sağlayıcı) belirler**. Bu durum sağlık hizmetinin klasik serbest piyasa kurallarına uymamasının temel nedenidir.",
