    "explanation": "Nefrotik sendrom gibi ağır renal protein kaybı durumlarında albümin ve düşük molekül ağırlıklı proteinler idrarla kaybedilirken, karaciğer onkotik basınç düşüşünü telafi etmek amacıyla büyük molekül ağırlıklı proteinlerin sentezini artırır; bu süreçte **Alfa-2 makroglobulin** ve **Haptoglobin** serum düzeyleri belirgin olarak yükselir.",
