    "question": "Patojen riketsiyaların antijenik yapıları arasındaki farklar sınıflandırmada, grup ve\ntürlere ayrılmasında yardımcı olur. Patojen olan riketsiyalari 5 serogrup veya biotipe\nayrılmıştır. Aşağıdakilerden hangisi bunlardan değildir",
