    "q_num": 82,
    "question": "Balık temizlerken elini bıçak kestikten bir hafta kadar sonra ağrılı, koyu menekşe\nrengi, ülsere lezyonu olan hastada lezyondan ve kandan alınan kültürde Gram pozitif,\nhareketsiz, sporsuz, katalaz negatif, TSI besiyerinde H2S üreten basiller üremiştir. Tablodan\nsorumlu olabilecek en olası etken aşağıdakilerden hangisidir?",
