    "explanation": "Periferik kan yaymasında eritrositlerin içinde kenara yapışık çoklu halka formları (akole formlar) ve eritrositleri parçalamaksızın görülen tipik **hilal veya muz şekilli gametositler**, malign tersiyan sıtma etkeni olan **Plasmodium falciparum**'un patognomonik mikroskobik görüntüsüdür.",
