    "explanation": "Bir timidin analoğu olan **zidovudin (AZT)**, viral revers transkriptaza yüksek afiniteyle bağlanır ve sentezlenmekte olan proviral DNA zincirine katılarak 3'-hidroksil grubu eksikliği nedeniyle fosfodiester bağının kurulmasını engeller; böylece DNA zincir uzamasını sonlandırır.",
