        "letter": "A",
        "text": "Bakteri Virülansı; Bakterilerin konak dokularında hasara neden olması demek olup konak hücrelerine bağlanma, hücrelerle dokuları invaze edebilme veya toksin salgılayabilme yeteneklerine bağlıdır."
