    "subject": "Enfeksiyon Hastalıkları",
    "q_num": 13,
    "question": "Bebek ve küçük çocuklarda ateşin düşmesini takip eden günlerde yaygın kısa süren\nmakülopapüler döküntü ile giden hastalık hangisidir?",
