    "options": [
      {
        "letter": "A",
        "text": "Kızamık"
      },
      {
        "letter": "B",
        "text": "Roseola infantum"
      },
      {
        "letter": "C",
        "text": "Kızamıkçık"
      },
      {
        "letter": "D",
        "text": "Eritema infeksiyozum"
      },
      {
        "letter": "E",
        "text": "Su çiçeği"
      }
    ],
    "answer": "B",
