    "explanation": "Bakır taşıyıcı protein olan **seruloplazmin**, serum protein elektroforezinde **Alfa-2** globulin bandında göç eder; transferrin, beta-lipoproteinler (LDL), hemopeksin ve C3 kompleman ise beta bandında yer alır.",
