    "explanation": "Tip I (IgE aracılı) şiddetli penisilin alerjisi öyküsü bulunan hastalarda beta-laktam çekirdeği taşımayan makrolid grubu antibiyotikler (**azitromisin**, klaritromisin) en güvenli ve etkili alternatif seçenektir.",
