    "explanation": "Üriner antiseptik olan **nitrofurantoin**, bakteri içi flavoprotein nitroredüktazlar tarafından ve asidik idrar ortamında indirgenerek reaktif ara metabolitlere dönüşür; bakteriyel ribozomal proteinleri ve DNA'yı hasara uğratarak akut sistitte etkili olur.",
