    "explanation": "Dördüncü kuşak bir florokinolon olan **moksifloksasin**, C-8 pozisyonundaki metoksi grubu sayesinde *Bacteroides fragilis* dahil anaerobik bakterilere ve Gram-pozitif koklara karşı güçlü etkinlik sergileyen tek kinolondur.",
