    "explanation": "Bir 5-nitroimidazol türevi olan **metronidazol**, DNA zincir kırıkları oluşturarak hem *Clostridioides difficile* kaynaklı psödomembranöz kolitte hem de *Giardia* ve *Trichomonas* gibi protozoon enfeksiyonlarında oral yolla kullanılır.",
