    "explanation": "Minosiklinin 9-t-bütilglisilamido türevi bir glisisiklin olan **tigesiklin**, klasik tetrasiklin direnç mekanizmalarını (eflüks ve ribozomal koruma) aşarak MRSA, VRE ve dirençli pnömokok enfeksiyonlarında **yalnızca intravenöz (IV)** yoldan kullanılır.",
