    "explanation": "Aminoglikozid antibiyotikler içinde *Pseudomonas aeruginosa*'ya karşı intrensek bakterisid gücü en yüksek (en düşük MİK değerine sahip) olan ajan **tobramisindir**; kistik fibrozis alevlenmelerinde inhaler ve IV yolla tercih edilir.",
