    "subject": "Mikrobiyoloji",
    "q_num": 41,
    "question": "Son üç gündür ateş, öksürük, kusma ve ishal yakınmaları nedeni ile semptomatik\nilaçlar kullanmakta olan sekiz yaşındaki bir kız çocuğu, yüzünde ve gövdesinde yeni ortaya\nçıkan döküntüler nedeni ile polikliniğe tekrar getirilmiştir. Yapılan muayenesinde\nyanaklarında bilateral eritemli kelebek şeklinde döküntü ile birlikte, her iki omuz ve\nkollarında eritemli, kaşıntılı döküntü saptanmıştır.Tanımlanan klinik bulgular dikkate\nalındığında akla getirilmesi gereken en olası klinik tablo ve etkeni aşağıdaki seçeneklerden\nhangisinde doğru verilmiştir?",
