    "explanation": "Çocukluk çağında yanaklarda eritemli \"tokatlanmış yüz\" görünümünün ardından gövde ve ekstremitelerde retiküler (dantelsi) kaşıntılı döküntü ile karakterize 5. hastalık tablosu **Erythema infectiosum** olup etkeni tek iplikli DNA virüsü olan **Parvovirus B19**'dur.",
