    "question": "Otel tatilinden 2 gün önce döndüğünü belirten hasta, ateş, ishal, gözlerde yanma,\nbatma ve kızarıklık şikayetlerini belirtiyor. Yapılan muayenesinde konjunktivalarda\nhiperemi, kemozis, preaurikuler lenfadenopati saptanan hastanın biyomikroskopla yapılan\ngöz muayenesinde akut folliküler konjunktivit geçirdiği saptanıyor.Tanımlanan tabloya neden\nolabilen etken virus aşağıdakilerden hangisi olabilir?",
