    "question": "Bir deneyde bakterilerin nötrofiller tarafından fagositozu incelenmiştir. Bakteriler\nnötrofil plazmasına girer. Streptococcus Pneumoniae, Haemophilus influenzae ve Neisseria\nmeningitidis fagositozunun Enterobacteriaceae ile karşılaştırıldığında azaldığı gözlenir. Bu üç\nbakteride aşağıdaki immün kaçınma mekanizmalarından hangisi bu bulguyu en iyi şekilde\naçıklıyor?",
