    "subject": "Patoloji",
    "q_num": 88,
    "question": "26 yaşında bir erkek, enjeksiyonla uyuşturucu kullanan bir kişidir. Yakınlarda ateşi\nyükseldi. Muayenede, bir kalp üfürümü duyuluyor. Kan kültürü Staphylococcus aureus için\npozitiftir ve antibiyotik duyarlılık testi direnç gösterir metisiline (bu organizmalarda mecA\ngeninin varlığı nedeniyle). Bu adaptasyon aşağıdaki mekanizmalardan hangisiyle (Metisilin\ndirencini kazanma) yapılmıştır?",
