    "answer": "C",
    "note": null,
    "explanation": "*Staphylococcus aureus*'un metisiline direnç kazanması (MRSA), PBP2a enzimini kodlayan mecA genini taşıyan stafilokoksik kaset kromozomun (**SCCmec patojenik adasının**) yatay gen transferiyle bakteri kromozomuna entegre olması sonucu gerçekleşir.",
