    "subject": "Patoloji",
    "q_num": 90,
    "question": "20 yaşında bir kadın 2 gündür giderek artan hezeyan geçiriyor ve hastaneye\nkaldırılır. Fizik muayenede, mukozada kirli beyaz, sert bir zar ile ile akut farenjiti var.\nVibratuar sensasyonun azaldığı paresteziler mevcuttur. Oskültasyonda, düzensiz kalp ritmi\nsaptanıyor. Göğüs röntgeni kardiyomegali gösterir. Faringeal membranın Gram boyaması\nfibrinopürülan bir doku içinde çok sayıda küçük gram-pozitif basiller gösteriyor.\nAşağıdakilerden hangisi en olası mekanizmadır bu hastada kalp hastalığı gelişmesi açısından?",
    "professor": "Bülent Mızrak",
    "options": [
      {
        "letter": "A",
        "text": "Ekzotoksin ile oluşan hücre hasarı"
      },
      {
        "letter": "B",
        "text": "Granülomatöz inflamasyon"
      },
      {
        "letter": "C",
        "text": "Lipopolisakkarid ile oluşan hipotansiyon"
      },
      {
        "letter": "D",
        "text": "Mikroabse formasyonu"
      },
      {
        "letter": "E",
        "text": "Tromboz ile birlikte vaskülitis"
      }
    ],
    "answer": "A",
    "note": null,
    "explanation": "*Corynebacterium diphtheriae* kökenli difteri ekzotoksini, sistemik dolaşımla kalbe ulaşarak miyositlerde EF-2'yi ADP-ribozilleyip protein sentezini durdurur ve fatal seyredebilen toksik miyokardite neden olur.",
