    "explanation": "Zoonotik kaynaklı akut viral solunum yolu salgınlarında enfekte bireyleri erken dönemde hızla saptamak ve izolasyona almak için en duyarlı ve özgül tanı yöntemi **RT-PCR tabanlı moleküler RNA testleridir**.",
