    "subject": "Biyokimya",
    "q_num": 15,
    "question": "17.Aşağıdakilerden hangisi, akut faz yanıtı sırasında karaciğer tarafından sentezlenen\nbazi proteinlerin proteoliz sonucu olustugunu en iyi açıklar?",
