    "question": "31.Aşağıdaki ilaç etki mekanizmasi eşleştirmelerini yapınız\nTranspeptidaz enzimlerini irreversibl olarak inhibe ederek etki gösterirler>>>beta\nlaktama\nSitoplazma membran permeabilitesini bozarak etki eder>>>  Gramisidin\nBakteri ribozomlarında protein sentezi inhibe ederek>>> tetrasiklinler\nDNA firaz (topoizomeraza II) veya topoizomeraz IV inhibisyonu>>> kinonlar\n32.Aşağıda verilen eşleştirmeleri yapınız\nBakteri hücresinin direkt olarak öldürülüp yok edilmesidir>>> bakterisid etki\nAntimikrobik ilaçların bakteriyostatik etki gücünün bir kantitatif göstergesidir>>> MİK\nNormalde düşük dozlarda etkili olan ilacin etkisini gösterebilmesi için tedavide daha\nyüksek dozlara gerek duyulmasidir.>>> Tolerans\nAntibiyotik konsantrasyonunun MIK degerinin altina düşmesini rağmen antibakteriyel\netkinin bir süre daha devam etmesidir.>>> postantibiyotik etki\n33..……bakterisid etki gücünün göstergesidir\nMBK\n34.Aşağıdaki ilaç kombinasyonlarından hangisi, beta laktamaz enzim inhibitörünün\nkullanildigi bir preparat olamaz?",
