    "question": "60.62 yaşında erkek hasta, osteoartrit nedeniyle sağ dizine yapılan intraartiküler\nenjeksiyondan üç gün sonra şiddetli diz ağrısı, şişlik, kızarıklık ve ateş şikayetiyle acil\nservise başvurmuştur. Fizik muayenede diz eklemi palpasyonla asiri hassastir ve\nbelirgin efüzyon saptanmıştır. Hastadan alınan eklem sivisi pürülan görünümdedir ve\nGram boyamasında bol nötrofil ile birlikte gram-pozitif, kümeler oluşturan koklar\ngörülmüştür.\nBu hastada septik artrite yol açan etkenin patogenezinde asagidakilerden hangisinin\nbirincil rol oynamasi beklenmez?",
