    "subject": "Mikrobiyoloji",
    "q_num": 62,
    "question": "68.Bir motosiklet kazasi sonrasi bacaginda derin bir laserasyon (kesik) ve abrazyon\n(sıyrık) olusan 28 yasindaki bir erkek, yara yerini evde yüzeysel olarak temizlemistir\nKazadan iki gün sonra, yara yerinde ani başlayan ve hızla artan siddetli agni, bacakta\ngerginlik ve sislik gelismesi üzerine acil servise başvurmuştur . Muayenede, yara\ngevresindeki cildin bronz-mor bir renk aldığı, yaradan kötü kokulu, sulu bir akıntı geldi\nve cilt alti dokulara elle bası uygulandığında çıtrıtı sesi alindigi saptanmistir. Hastanin\nategi 39°C, kan basinci 80/50 mmHg ve nabzi 120/dk olarak ölçülmüştür Hastada\ngelişen bu durumun en olasi etkeni aşağıdakilerden hangisidir?",
