    "question": "70.32 yasinda, TOrk Hava Yollarinda kabin memuru olan kadin hasta, 4 gün önce\ntamamladığı Lagos (Nijerya) uçuşu sonrasi Türkiye'ye dönmüştür. Donüşünden 3 gün\nsonra başlayan, titremeyle yükselen ateş, şiddetli  baş ağrısı bulanti ve genel durum\nbozuklugu şikayetiyle acı servise başvurmuştur . Geldiginde bilinç bulanıklığı olan\nhastanin ateşi 40.2°C olarak ôlçülmüstür. Yapilan periferik yayma incelemesinde,\neritrositlerde birden fazla tasli yuzuk formu ve %9 oranında parazitimi saptanmistir.\nBu hastada en kısa sürede başlanması gereken hayat kurtanci tedavi aşağıdakilerden\nhangisidir?",
