    "explanation": "Endemik bölge seyahati sonrası bilinç bulanıklığı, hiperparazitemi (%9) ve çoklu yüzük formları ağır **Plasmodium falciparum** sıtmasına (serebral sıtma) işaret eder; güncel kılavuzlarda hayat kurtarıcı birinci basamak acil tedavi **intravenöz artesunat**'tır. Klorokin direnç nedeniyle ağır tabloda kullanılmaz.",
