    "subject": "Mikrobiyoloji",
    "q_num": 66,
    "question": "72.Rahim içi araç (RIA) kullanan 35 yasindaki bir kadin, alt karin agrisi, ates ve vajinal\nakinti şikayetleri ile başvuruyor. Pelvik muayenede apse gelistigi saptaniyor ve apse\nmateryalinden alinan ömekte makroskopik olarak sari granüller gözleniyor. Bu\ngranüllerin ezilerek hazırlanan preparatinin Gram boyamasında, Gram-pozitif,\ndallanan, filamentöz basiller görülüyor.\nBu kinik tablodan sorumlu olan en olasi etken aşağıdakilerden hangisidir?",
