    "explanation": "RİA kullanan kadınlarda pelvik apse materyalinde makroskopik sarı granüller («sülfür granülleri») ve mikroskopide Gram-pozitif, dallanan filamentöz basillerin görülmesi **Actinomyces israelii** enfeksiyonu için patognomoniktir. Nocardia aerobik ve kısmi aside dirençli boyanırken Actinomyces anaerobiktir.",
