    "explanation": "Yenidoğan menenjitinde BOS'ta Gram-pozitif basil saptanması, kanlı agarda dar beta-hemoliz yapması, katalaz pozitifliği ve oda sıcaklığında (25°C) takla atma hareketi göstermesi **Listeria monocytogenes** için patognomoniktir. S. agalactiae katalaz negatif kok, B. anthracis ise hareketsiz geniş basildir.",
