    "answer": "C",
    "note": null,
    "explanation": "Bilateral parotis bezi şişliği ve hassasiyeti (parotit) sonrasında orşit tablosunun gelişmesi, MMR aşı eksiği olan ergenlerde Paramyxoviridae ailesinden tek sarmallı RNA virüsü olan **Kabakulak virüsü (Mumps)** enfeksiyonunun klasik klinik tablosudur. EBV tonsillofarenjit ve lenfadenopatiyle seyreder.",
    "id": "K2_2025-2026_Q75"
