    "q_num": 78,
    "question": "84.Yenidoganin kan kültüründe Gram pozitif koklar üremistir.\nLaboratuvar testleri şöyledir.\n• Katalaz: Negatif\n• Basitrasin duyarlığı : Dirençli\n• SXT duyarlığı: Dirençli\n• CAMP testi: Pozitif\n• Hippürat hidrolizi: Pozitif\n• PYR testi: Negatif\n• Safra-eskülin: Negatif\nBu bulgulara göre olasi etken mikroorganizma aşağıdakilerden hangisidir?",
