    "question": "100.Bir immünoloji laboratuvarında, sağlıklı bir bireyden alınan periferik kan\nlökositleri; IgG ve C3b ile opsonize edilmis ve yesil floresan protein (GFP) eksprese\neden bir Staphylococcus aureus suşu ile birlikte inkübe edilmistir. Farkh hücre\npopulasyonlarının bu patojeni fagositoz kapasitelerini değerlendirmek için yeterli\ninkübasyon süresinin ardından akim sitometri cihazında analiz edilmis ve hücre içi\nyeşil floresan sinyali değerlendirilmiştir\nAşağıdaki lökosit populasyonlarindan hangisinin, bu test koşullarında anlamli\ndüzeyde hücre içi floresan sinyali göstermesi beklenmez?\n(İptal edildi)",
